19	 * Sezione dei tag associabili, con vincolo rigido: considera solo i gruppi
20	 * filtrati per l'entità data e per il target dato (entity|asset) e produce,
21	 * per ogni gruppo, un Fieldset con un unico NestedCheckboxSelect le cui
22	 * categorie collassabili sono le TagCategory del gruppo. Condiviso fra i form
23	 * delle entità e il picker degli asset nell'AssetManager.
24	 */
25	class TagPicker
26	{
27	    /**
28	     * Picker legato alla relazione `tags` del record del form (entità che usa
29	     * HasTags): ogni NestedCheckboxSelect di gruppo carica/sincronizza sul
30	     * pivot `taggables` i soli tag delle proprie categorie (il suo
31	     * "universo"), senza toccare quelli degli altri gruppi che condividono la
32	     * stessa relazione.
33	     *
34	     * `$scopeGroupsUsing` (opzionale) restringe ulteriormente i gruppi: riceve
35	     * la query dei TagGroup come parametro nominato `query` e viene valutata da
36	     * Filament, quindi supporta l'injection dei parametri di contesto (es.
37	     * `$livewire`). Permette all'app vincoli propri (es. la Destinazione
38	     * Category1) senza che il package li conosca.
39	     */
40	    public static function make(string $entityAlias, TagTarget $target, ?Closure $scopeGroupsUsing = null): Section
41	    {
42	        // schema lazy: i gruppi possono dipendere dal contesto ($livewire) via
43	        // $scopeGroupsUsing, valutato da Filament sul componente
44	        return self::section()->schema(function (Section $component) use ($entityAlias, $target, $scopeGroupsUsing): array {
45	            $scopeGroups = $scopeGroupsUsing === null ? null : function (Builder $groupQuery) use ($component, $scopeGroupsUsing): void {
46	                $component->evaluate($scopeGroupsUsing, ['query' => $groupQuery]);
47	            };
48	
49	            return array_map(
50	                fn (TagGroup $group): Fieldset => self::relationshipGroupFieldset($group),
51	                self::groups($entityAlias, $target, $scopeGroups),
52	            );
53	        });
54	    }
55	
56	    /**
57	     * Picker "standalone" (senza relationship): lo stato è un array di id tag
58	     * per categoria, sotto la chiave `tags` (`tags.{categoryId}` => int[]).
59	     * Per contesti senza record bindato al form (es. azione nell'AssetManager),
60	     * dove fill/sync sono gestiti a mano dal chiamante.
61	     */
62	    public static function makeStandalone(string $entityAlias, TagTarget $target): Section
63	    {
64	        return self::section()->schema(fn (): array => array_map(
65	            self::groupFieldset(...),
66	            self::groups($entityAlias, $target, null),
67	        ));
68	    }
