75	    /**
76	     * Fieldset del gruppo per la variante standalone, con un select per ogni
77	     * sua categoria (con almeno un tag).
78	     */
79	    private static function groupFieldset(TagGroup $group): Fieldset
80	    {
81	        return Fieldset::make((string) $group->name)
82	            ->columns(2)
83	            ->columnSpanFull()
84	            ->schema(
85	                $group->categories
86	                    ->filter(fn (TagCategory $category): bool => $category->tags->isNotEmpty())
87	                    ->sortBy('id')
88	                    ->map(self::categorySelect(...))
89	                    ->values()
90	                    ->all(),
91	            );
92	    }
93	
94	    /**
95	     * Fieldset del gruppo per la variante con relationship: un unico
96	     * NestedCheckboxSelect le cui categorie collassabili sono le TagCategory
97	     * del gruppo (con almeno un tag) e i cui item sono i loro tag. Lo stato è
98	     * caricato/salvato sulla relazione `tags`, ristretto all'universo dei tag
99	     * di queste categorie: più Fieldset di gruppo possono così condividere la
100	     * stessa relazione senza toccare le selezioni degli altri gruppi.
101	     */
102	    private static function relationshipGroupFieldset(TagGroup $group): Fieldset
103	    {
104	        $categories = $group->categories
105	            ->filter(fn (TagCategory $category): bool => $category->tags->isNotEmpty())
106	            ->sortBy('id')
107	            ->values();
108	
109	        return Fieldset::make((string) $group->name)
110	            ->columnSpanFull()
111	            ->schema([
112	                NestedCheckboxSelect::make('tags_group_' . $group->id)
113	                    ->hiddenLabel()
114	                    ->relationship('tags', Tag::class, TagCategory::class, 'tag_category_id', '')
115	                    ->categories($categories)
116	                    ->items($categories->flatMap(fn (TagCategory $category) => $category->tags)),
117	            ]);
118	    }
119	
120	    /**
121	     * Select multiplo con i tag della categoria come opzioni. Lo statePath
122	     * annidato `tags.{categoryId}` tiene tutte le selezioni sotto `tags`.
123	     */
124	    private static function categorySelect(TagCategory $category): Select
125	    {
126	        $options = [];
127	        foreach ($category->tags as $tag) {
128	            $options[(int) $tag->id] = (string) $tag->name;
129	        }
130	
131	        return Select::make('tags.' . (int) $category->id)
132	            ->label((string) $category->name)
133	            ->multiple()
134	            ->searchable()
135	            ->options($options)
136	            ->default([]);
137	    }
138	
139	    /**
140	     * Gruppi filtrati per entità e target, più l'eventuale vincolo aggiuntivo
141	     * passato dal chiamante, con le loro categorie (e relativi tag). Le
142	     * categorie senza tag e i gruppi rimasti senza categorie sono esclusi.
143	     *
144	     * @param (Closure(Builder<TagGroup>): void)|null $scopeGroups query dei TagGroup
145	     * @return array<int, TagGroup>
146	     */
147	    private static function groups(string $entityAlias, TagTarget $target, ?Closure $scopeGroups): array
148	    {
149	        $groupQuery = TagGroup::query()
150	            ->where('entity_type', $entityAlias)
151	            ->where('target', $target->value)
152	            ->whereHas('categories', function (Builder $categoryQuery): void {
153	                $categoryQuery->whereHas('tags');
154	            })
155	            ->with('categories.tags')
156	            ->orderBy('id');
157	
158	        if ($scopeGroups !== null) {
159	            $scopeGroups($groupQuery);
160	        }
161	
162	        return $groupQuery->get()->all();
163	    }
164	}
