public function test_tag_list_links_the_group_to_its_category_list(): void
{
    $response = $this->get(AssetTagResource::getUrl('index', [
        'group' => $this->group,
        'category' => $this->category,
    ]));

    $response->assertOk();

    $categoriesUrl = AssetTagCategoryResource::getUrl('index', ['group' => $this->group]);

    // il gruppo è un link alla lista delle sue categorie
    $this->assertMatchesRegularExpression(
        '~<a[^>]+href="' . preg_quote($categoriesUrl, '~') . '"[^>]*>\s*Tag Asset Prodotti\s*<~',
        $response->getContent() ?: '',
    );
}

